contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint256 beforeLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        c.AdjustBetAmounts(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        assert((!reverted && afterLimit == amount && afterBalance == beforeBalance) ||
               (reverted && afterLimit == beforeLimit && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

