pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeLimit = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.AdjustBetAmounts(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterLimit;
        try c.currentBetLimit() returns (uint256 __r) { afterLimit = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue((!reverted && afterLimit == amount && afterBalance == beforeBalance) ||
               (reverted && afterLimit == beforeLimit && afterBalance == beforeBalance));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
